quests[74443] = { id = 74443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is Another Dragon's Treasure?", description = "I must admit, I am out of my depth here. \n\nIt is of black dragon make. The decoration on the pommel matches, but I have no idea what it is. Which I suppose is the point.\n\nI have heard you have travelled the Isles. Do you have any recommendations on who to talk to?", progress = "It is a fascinating object. I am tempted to tell Evorian it's a weapon just to see what happens when he tries to use it... but I suppose not. It might actually be really dangerous.\n\nWould be fun to see his scales singed a bit though.", completion = "You think this Veritistrasz could help? I am willing to give it a shot!\n\nGood suggestion, {name}.", objectives = "Talk to Voraxian in the Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74444] = { id = 74444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/3 C and D" }
quests[74445] = { id = 74445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/1 C and D" }
quests[74447] = { id = 74447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbal Archaeology", description = "Where should we meet this Veritistrasz of yours?\n\nRuby Lifeshrine? Are you sure this is not an attempt to introduce me to Alexstrasza? \n\nNo? Well then! I shall meet you at the Ruby Lifeshrine!", progress = "Let us hope this is something exciting!", completion = "Well, that is a bit of a disappointment.\n\nI suppose an old egg-tending device is some form of culture, even if it is not very exciting. \n\nIf you find something else of interest in the vaults, I would be interested in looking at it.", objectives = "Talk to Veritistrasz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
