quests[74476] = { id = 74476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slime Dies When You're Having Fun", description = "The investigators here told me that there were some side effects to removing the time anomaly from Eon's Fringe. Seems a bunch of slimes snuck through the timestream in the process. \n\nOh! Oh! Time slimes! They're Time slimes! Ha.\n\nAnyway, could you take some of them out?", completion = "I recorded the sounds of you killing the slimes for reference. I hope that's okay.", objectives = "Kill 12 Time Slimes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74488] = { id = 74488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runaway Rusziona", description = "Black whelps have the agility of a rock, but they try to make up for it with the most impressive top speed. Try to take it easy around those corners!\n\n: Dash forward.\n: Stops forward movement.\n: Restores all Vigor. Must be grounded.", progress = "How is the racing going?", completion = "Well done!", objectives = "Help Rusziona glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74489] = { id = 74489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zhoomsa", description = "Bronze whelps can be careless when trying to win, so be careful with the timeways!\n\n: Transform into an adult and gain improved speed.\n: Restore 1 Vigor until all Vigor has been recovered.\n: Resets cooldowns.", progress = "How is the racing going?", completion = "Well done!", objectives = "Help Zhusadormu glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74490] = { id = 74490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaleth on the Go", description = "Blue whelps will try to skip ahead where they can, but be careful blinking through rings!\n\n: Blink forward and dash.\n: Increases forward acceleration.\n: Consumes Arcane Acceleration and restores Vigor.", progress = "How is the racing going?", completion = "Well done!", objectives = "Help Zalthgos glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74491] = { id = 74491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pole Position Posidriss", description = "Green whelps have an affinity for short naps and bursts of speed, so do your best to keep pace.\n\n: Fly up then restore 1 Vigor.\n: Adds 5 sec to Winds of Life's duration.\n: Anytime you restore Vigor, dash forward.", progress = "How is the racing going?", completion = "Well done!", objectives = "Help Posidriss glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74492] = { id = 74492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blistering Belastrasza", description = "Red whelps can be a little out of control, so best of luck!\n\n: Consumes all Vigor over time.\n: Restore all Vigor, boosting forward each time.\n: Consumes Crimson Flight, resets cooldowns.", progress = "How is the racing going?", completion = "Well done!", objectives = "Help Belastrasza glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74493] = { id = 74493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Time Is The Charm", description = "<Voraxian bounces the Odd Round Object in his hands a few times.>\n\nHmm, it lands in the hand well, like it was made for this. Let us talk to Veritistrasz and see if he knows more.", progress = "Let us hope it is something exciting this time!", completion = "By the Titans... talk about putting my claw in my jaw. \n\nSorry {name}, I will sit here for a bit with Veritistrasz and wait until he is ready to talk again. \n\nIf you find anything else of interest, please do bring it along.", objectives = "Determine the origin of the Odd Round Object.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74494] = { id = 74494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scale for a Scale", description = "The elder waking was a threat, certainly. But there is one more mission I must complete before we depart, lest we lose our only chance to complete it at all.\n\nHowever different the Zaqali tribe may be from the Qalashi, they are still dragonslayers. Their implements of war are no less deadly to our kind.\n\nI need a spear on par with the one we saw at the elder's side. Find the largest one you can and deliver it to me.", progress = "Djaradin weapons are vile creations, but they were created for one task and one task alone.", completion = "This is the only way forward.", objectives = "Collect a Zaqali Dragonslayer's Spear for Sabellian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74495] = { id = 74495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tale of Hraxian", description = "Hello {name}, it is good to see you.\n\nWould you like to join us around the fire? I think it is time we heard a positive story about the obsidian flight of old.\n\nI once promised yourself and Voraxian I would tell you the story from the vase you found in the Zskera Vaults. I believe it is that time.", progress = "It is always a pleasure, {name}.", completion = "<Veritistrasz sits in silence for a short while.>\n\nThank you for listening, {name}. I have forgotten much over my life, but not this. \n\nI hope Hraxian's story gives the obsidian flight hope after the discoveries we made here.", objectives = "Listen to the tale of Hraxian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
