quests[74513] = { id = 74513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74514] = { id = 74514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slowest Fan Club", description = "Has a crowd ever roared for you? Everyone shouting your name, pushing you on to victory? \n\nI want to give that same feeling to Slick. Give him the taste of being a champion.\n\nCourse, we don't speak snail, so we can only be so useful. Round up some snails that could use purpose in their lives. Slick needs a fan club.", progress = "A race track ain't no race track without fans to watch the race. That's just facts.", completion = "Perfect! Stick some Big Slick in the City merchandise on these critters and they're ready to go. Our boy's going to be more motivated than ever.", objectives = "Collect 8 Aimless Snails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74515] = { id = 74515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snail Mail", description = "Racing snails are all about speed, but riding snails? They need stamina to boot.\n\nI owe some supplies to a buddy in Loamm. Why don't you make the delivery for me? Help build Slick's endurance.\n\nOh, and make sure you don't dismount. Not much of a training session if you keep hopping off and on.", progress = "This buddy of mine, always asking for supplies. I got snails to train!", completion = "Speed and stamina! This snail has it all, folks. Well done.", objectives = "Deliver the package to Terryn in Loamm without dismounting Slick. If you get dismounted from Slick, Briggul can give you a new delivery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74516] = { id = 74516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Snail's Pace", description = "It's an off day for our local racing track, so I figured we could take the opportunity to build up Slick's speed. Grow some confidence on his home turf, I'm thinking.\n\nTake two laps around the track. Let's see how your training is coming along!", progress = "Not every day needs to be at a hundred, you know? Even in the fast-paced world of snail racing.", completion = "Look at you two, tighter than mucus brothers. Oh, that's what I call it when two snails get stuck to each other. Happens.\n\nYou're both coming along just fine. Can't wait to see where you go!", objectives = "Collect 1 Lap Markers by doing two laps around the snail track.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74517] = { id = 74517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Terrain Snail", description = "While life in these caverns is plenty exciting, Slick has a future in the world above. Namely as your trusty mount. \n\nWhich means he needs to prepare for all sorts of environments.\n\nLuckily, the Dragon Isles has biomes to spare. Why don't you take him for a spin? Give him a taste of what's to come. One lap per location should do the trick.", progress = "I don't do too well above ground, myself. All that sunlight and fresh air just plays havoc on my sinuses.", completion = "Here comes Slick, traveler extraordinaire! Mucus seems alright, membranes nice and translucent, no cracks in the shell. \n\nThanks for taking care of him.", objectives = "Ride Slick through Snail Markers in Restless Wetlands, Wanderer's Steppe, Upper Frostlands, and Shifting Sands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74518] = { id = 74518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resistance Training", description = "These caverns aren't easy on my poor snails, which is why I feed them a special crystal diet. Keeps their shells hard and gleaming. \n\nSlick eats more than his fair share though, so I'm plumb out. \n\nWould you collect some crystals in Zaralek Cavern? Get a nice mix, too. We need to make sure Slicks ready for every environment.", progress = "Everyone says they want their snails to have strong, healthy shells, but when it comes time to collect the crystals? They're too busy, they're too scared. \n\nCrokin' cowards..", completion = "That's the stuff! Just wait until you see how Slick's shell shines. Huh. Say that three times fast, am I right?", objectives = "Collect 5 Glowing Crystals, 5 Sulfuric Crystals, and 5 Magma Crystals from around Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74519] = { id = 74519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good for Goo", description = "Every snail trainer knows that it's all about the goo. The slime. The mucus. That's how you turn a speedy snail into a champion.\n\nSlick could use a good slather. Go out and collect some goo from the local slime trails to slick him up. Heh.", completion = "Now that's a slicked Slick if I ever did see one. Nice job.", objectives = "Collect Goo from slimes and oozes in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74520] = { id = 74520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Less Cargo", description = "Those djaradin think they own these caverns, coming around here and looting our supplies. How am I supposed to train champions under these conditions?\n\nCan you do me a favor and get those supplies back? I can't help you train Slick without them. \n\nBesides, the big fellow could use a rest day.", progress = "Shell polish, mucus paste, racing rocks... Crok it all, we need those supplies back!", completion = "Shell yeah! Way to put the work in. Now we can get back to Slick's training.", objectives = "Collect 10 Stolen Supplies from djaradin in Igira's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74521] = { id = 74521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flame, Extinguished", description = "Sarkareth is no more.\n\nHis hubris left him vulnerable to the dark influences that have assaulted our flight for millennia. Just like Neltharion before him.\n\nI believe Emberthal seeks more answers than what Wrathion and Sabellian are able to give. She may need some assistance.", progress = "Return to me if you'd like to help further.", completion = "Here we are, {name}.\n\nI admit that the black dragonflight's legacy is rife with moments that many would deem disreputable, vicious, or even vile.\n\nSo understand the weight of my words when I say that the contents of this edifice may be the worst of it.", objectives = "Speak to Wrathion or Sabellian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74522] = { id = 74522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants", description = "Some call me a miracle, you know. Yet my birth was anything but natural. I was crafted, much as the creatures in here were crafted. Many died painful, tragic deaths so that I could live.\n\nThis... callousness towards the living is something I wish to eradicate.\n\nTake this, and use it to destroy any intact specimen tanks we encounter. Nothing deserves to suffer like this.", progress = "We need to end this here.", completion = "Finally, the suffering of these abominations has come to an end.", objectives = "Destroy 7 Specimen Tanks with the Blacktalon Napalm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74523] = { id = 74523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Traitor's Due", description = "These sycophants shame themselves and the black dragonflight. It is clear that they are willing to die in service of my father's dark machinations.\n\nLet us not disappoint them.", progress = "We will never erase this mark on our legacy. But there is no way forward while they yet live.", completion = "Wrathion's Blacktalon may not be front-line soldiers, but they should be able to take care of the rest.", objectives = "Defeat the Neltharion Loyalists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74525] = { id = 74525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honorbound", description = "<The djaradin's body is gaunt and wasted, its life energy siphoned away by the hungry machines that power this dark laboratory.\n\nPerhaps there are other djaradin imprisoned here that can be spared from this horror.>", progress = "The black dragonflight is defined by our actions, not our accomplishments.", completion = "May they find the honor in death that was denied them in life.", objectives = "Free the imprisoned djaradin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74526] = { id = 74526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secured Shipment Looted" }
quests[74527] = { id = 74527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74528] = { id = 74528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74529] = { id = 74529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74538] = { id = 74538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blow It Up", description = "Make no mistake, the djaradin are experienced dragon killers. But right now their ruthless tactics are overshadowed by the devastating power of their battlefield ballistae, capable of taking out any threat from a long distance. \n\nI have lost many good soldiers to these potent weapons.\n\nIt is essential that we destroy the ballistae if we hope to level the playing field and take to the skies. It is possible that we may even be able to gain the upper hand in this war.", completion = "We can see the smoke from up here! Good job.", objectives = "Destroy the djaradin heavy weaponry in the Battlefield Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74539] = { id = 74539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning Their Defenses", description = "The Firecallers are a formidable force. Their powerful, lethal magic allows them to vaporize anything that comes near them.\n\nTheir strategic positioning on high ledges makes them difficult to reach, but we cannot allow them to continue causing destruction among our forces.\n\nThe fate of our forces depends on your success. Good luck!", progress = "Yes?", completion = "Another advantage taken from the enemy!", objectives = "Neutralize Zaqali Flametongues in the Battlefield Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74540] = { id = 74540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting Communications", description = "{name}, we need intel, and we need it now.\n\nSomewhere within one of the djaradin's encampments, you will find their field general. He is a seasoned and formidable opponent, responsible for many attacks on our forces. \n\nAccording to our field agents, he may possess crucial military orders outlining their next offense and the locations of their new supply lines.\n\nIt is imperative that we obtain these orders. We cannot allow the djaradin to gain the upper hand.", progress = "Report!", completion = "This is not what I expected, soldier.\n\nAccording to this report, the djaradin discovered a new dragon-like species living in the caves to the east.\n\n<Ignax puts his finger on the map.>\n\nThey also marked it as one of their assault points.", objectives = "Eliminate Warchanter Ronvath and obtain the Invasion Plans in the Battlefield Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74542] = { id = 74542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Air Superiority", description = "<As Ignax looks up, you see a small smile appear on his face.>\n\nFew of my soldiers have experience fighting alongside dragons. What a glorious day.\n\nTheir presence gives us confidence, {class}. Now we must put an end to the djaradin's advance once and for all.", completion = "This must be the nesting area mentioned in the stolen report.\n\nBut why are the djaradin here dead?\n\nAre we too late?", objectives = "Defeat the djaradin forces and stop their advance in the Battlefield Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74557] = { id = 74557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigating the Unknown", description = "We can only assume that something ambushed the marching djaradin. Who could have done this? \n\nWe should investigate it before we proceed.", completion = "So, the djaradin were stopped here by an unknown dragonkin force. Judging by how many lie dead, these dragonkin are as brutal as the djaradin. \n\nWhat worries me the most is that they still carry Neltharion's banner, which means they remain loyal to him and whatever task he once gave them. \n\nWe must be careful--this has just got more complicated.", objectives = "Investigate the origins and motivations of the creatures in the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74562] = { id = 74562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Them Out", description = "Cages, chains and transportation carts... I think we all know where this leads.\n\nIf the drakonids plan on capturing and enslaving the slitherdrakes, then they are no better than the djaradin. \n\nSee what you can do to thwart their plans.", completion = "The slitherdrakes are free! Well done, {name}.", objectives = "Disrupt the poachers and stop them from capturing the slitherdrakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74563] = { id = 74563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worst of the Worst", description = "Everything here suggests this is a well-coordinated effort. These slitherdrakes are almost like wild beasts. They will not stand a chance without our aid.\n\nFind whoever is leading their operation and put an end to this.", completion = "So the slitherdrakes were not born here, but inside Aberrus?   Were they part of his experiments that ultimately led to the creation of the dracthyr? When I think about that, it horrifies me how easy it was for Neltharion to both create and destroy life.   Nevertheless, that was a decisive blow to their operation.", objectives = "Find and eliminate drakonid leading the poachers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74568] = { id = 74568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Who Would Burn Us", description = "The djaradin and their Primalist allies are a stain upon the land, {name}.\n\nWipe them from it.", progress = "How goes the battle?", completion = "Good. Nothing stops a ritual quite like killing the ritualist.", objectives = "Slay djaradin and Primalists assaulting the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74569] = { id = 74569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deny Them Resources", description = "This entire invasion has been carried out with the sole objective of infusing raw materials with elemental power on an unprecedented scale.\n\nWhile we may not know Fyrakk's ultimate goal, frustrating his efforts seems straightforward enough.\n\nIf he wants these materials, we will deny them to him.", progress = "Leave him nothing.", completion = "Excellent. Anything we can take from him buys us time.", objectives = "Recover infusion supplies from Fyrakk's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74570] = { id = 74570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid Our Wounded", description = "{name}, our forces were not prepared for such an onslaught.\n\nThese djaradin fight with more furor than the forces we have faced in the past. We have wounded behind enemy lines.\n\nIf you possess knowledge of how to heal then I ask you employ it. If you do not, we have bandages to aid the wounded with. \n\nPlease help bring our people out of the fire.", progress = "Our healers cannot be everywhere at once. Nor will they last long behind enemy lines.", completion = "Many have fallen to these invaders who desecrate our sacred plains. Thank you for stemming the tide of death today.", objectives = "Heal 6 Wounded Guardians using the provided bandages or your own abilities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74571] = { id = 74571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear a Path", description = "The djaradin are fortifying their beachhead. We cannot allow them to dig in any deeper or we risk their advances becoming permanent.\n\nDestroy their barricades before that can happen.", progress = "Leave them nothing to cower behind.", completion = "With their defenses broken, it will be that much easier to repel their advances.", objectives = "Destroy djaradin barricades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74572] = { id = 74572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make it Rain", description = "The djaradin are setting the Plains ablaze with the reckless use of fire magic. We must act before these small sparks grow into a raging wildfire.\n\nA deep pool of fresh water can be found not far from here. Skim the surface on your drake to collect as much as you can carry, then fly over the djaradin camp to douse any flames beneath you.\n\nThis won't be enough to put out the larger blazes, but it will buy us time.", progress = "Quickly, before the blaze spreads!", completion = "I could see the plumes of steam from here. Excellent work, {name}.", objectives = "Extinguish fires across the djaradin camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74573] = { id = 74573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Support", description = "The Primalist portals must be destroyed if we are to prevent them from infusing these raw materials with elemental energy.\n\nUnfortunately, their structures are too heavily warded for any single attack, whether mortal or draconic, to do lasting harm.\n\nTogether, though, there is a way.\n\nTake this seed. Use it to weaken their defenses and we will be able to strike before they have a chance to react.", progress = "We are counting on you, {class}.", completion = "Well done. That should put them behind schedule.", objectives = "Weaken the portals' defenses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74576] = { id = 74576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restored Hakkari Bijou", description = "<The bijou fragments fit together with ease; drawn toward each other with minimal intervention.\n\nIt thrums gently with remnants of an ancient power. Too much to be of no consequence, yet too little to be of much use.\n\nSomeone, somewhere, would surely be interested in seeing your discovery.>", completion = "An old Hakkari bijou, eh? I dare not ask HOW you came into possession of it, but there is no mystery to its origin.\n\nShould you find yourself within the walls of Zul'Gurub again, keep an eye out for other treasures... and bring them to me.\n\nI will be seeing you again soon.", objectives = "Find somebody interested in the Restored Hakkari Bijou.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74581] = { id = 74581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Long Knives", completion = "Is that you, {name}? Look at how much you've grown! But why are you here? \n\nThey've sent you to deal with Gor'krosh? Thank the ancestors!", objectives = "Talk to Kaltunk in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74636] = { id = 74636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74695] = { id = 74695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zulian, Razzashi, and Hakkari Coins", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", completion = "Excellent - this set of coins will make a fine addition to my growing collection.\n\nHere's your token, as promised." }
quests[74696] = { id = 74696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi, Vilebranch, and Witherbark Coins", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", completion = "Excellent - this set of coins will make a fine addition to my growing collection.\n\nHere's your token, as promised." }
quests[74697] = { id = 74697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandfury, Skullsplitter, and Bloodscalp Coins", progress = "I seek the Paragons of Power known as the Coins of the Tribes.  They are the currency used by the various denizens of Zul'Gurub, and each is imbued with subtle but powerful mojo.\n\nThere are nine distinct kinds to be found.  Should you have any extra, I will trade you a Bargaining Token for a set of three.\n\nAnd yes, you will be bringing those right back to me soon enough.", completion = "Excellent - this set of coins will make a fine addition to my growing collection.\n\nHere's your token, as promised." }
