quests[74769] = { id = 74769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stemming the Irontide", description = "Unfortunately, we are not the only ones who took notice of opportunities in the Reach. \n\nOur scouts have sent word of pirate vessels moored offshore. The first longboats have apparently come ashore on our northeastern beaches.\n\nOur history is not theirs to plunder. If you come across these pirates, send them swimming back to their little boats.", completion = "You have my thanks. With luck, these brigands will take heed.\n\nWe're willing to defend these lands and the secrets they contain.", objectives = "Slay 10 Irontide Pirates on the Tempest Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74771] = { id = 74771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Key Hunting", description = "My pockets are empty. I have no more vault keys!\n\nSee if you can find any Zskera Keys, and Jeb and I will see what we can find. If we pool our keys, we can open a lot of doors.", progress = "Did you find any keys?", completion = "We also found some keys! I can't wait to open more doors!", objectives = "Find 3 Zskera Vault Keys in the Forbidden Reach and deliver them to Pathfinder Tacha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74774] = { id = 74774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Keys", description = "I have more keys! You can use these to open more locked doors!\n\nPlease, take these and use them within the chamber.You will be able to choose one of these rewards:", sourceObjective = "Take the keys.", sourceObjectiveStatus = "unverified-source-field" }
quests[74775] = { id = 74775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disciple of Fyrakk: Kretchenwrath", description = "<Fyrakk's disciple has fallen. Perhaps the remains of this beast will bring some comfort to those whose land has been ravaged.>", progress = "I heard you faced a disciple of Fyrakk.", completion = "So this is the beast who would swear their loyalty to such an Incarnate. Their zealotry has festered for ages upon ages of this world. \n\nI cannot even begin to fathom such a deep-seated hatred.\n\nThank you for ending this flame of wrath upon our plains.", objectives = "Collect the Head of Kretchenwrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74783] = { id = 74783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sound of Silence", description = "It has been so many years since Shandaral has known true silence. With luck, our actions today will allow the echoes of this cursed place to fade.\n\nYou are due back in the Isles, no doubt--and I think it is high time I fly there as well.", completion = "The aftermath of the conflict in Shandaral has hung over our flight like a pall for so many years. To think that Lanigosa has been toiling all this time to lay those spirits to rest...\n\nThank you for lending her your aid, {name}. You have once again shown yourself a true ally to my people.", objectives = "Return to Kalecgos in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74784] = { id = 74784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/3 (FR)" }
quests[74786] = { id = 74786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Shimmershell Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Well, that shimmershell certainly lives up to its name! Practically glowing brighter than this cavern's crystals. \n\nAbsolutely stunning snailwork, {name}.", objectives = "Summon a max-level Shimmershell Snail battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74787] = { id = 74787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Snail Away", description = "Hmm. You ever mount a snail before?\n\nI've trained generations of racing snail champions, but now I've come across my toughest case yet. Problem is he's too crokin' big. Straight up barred from competition.\n\nIt's a shame to keep such a prize specimen stuck in a bucket though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", progress = "The big guy's racing name is Big Slick in the City, but we just call him Slick.", completion = "He likes you! Well, he doesn't dislike you. Hard to tell with snails.\n\nNow you just need to come back here every day for Slick's training regimen. He may be slow now, but we'll get him up to speed.", objectives = "Introduce yourself to Slick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74792] = { id = 74792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're Full of Stars!", objectives = "Defeat Stargazer Zenoth in a Pet Battle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74794] = { id = 74794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Twice a Day", objectives = "Defeat the Malfunctioning Matrix in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74795] = { id = 74795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Odd Round Object", description = "<This object looked out of place in the Zskera Vaults. It is round, with three claw-like divots in it. Perhaps it is of interest to Voraxian.>", completion = "Hmm, round... clearly claw holes... squishes a bit... I have no idea what this is. Perhaps some form of thrown weapon?\n\nHow exciting!", objectives = "Bring the Odd Round Object to Voraxian in Rusza'thar Reach.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74796] = { id = 74796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dusty Vase", description = "<You have found a vase. It appears to represent a black dragon fighting what could be a djaradin. It could be something Voraxian is interested in.>", completion = "<Voraxian holds the vase up to eye level and squints at the carvings.>\n\nHmm, yes, I think you are right {name}. It does look like a djaradin. \n\nIt is a vase though. Unlikely to be too exciting. Do not get your hopes up.", objectives = "Bring the Dusty Vase to Voraxian in Rusza'thar Reach.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74835] = { id = 74835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enok the Stinky", objectives = "Defeat Enok the Stinky in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
