quests[74842] = { id = 74842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74847] = { id = 74847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emberthal Awaits", description = "We are by no means ready to relax, but at least our encampment here is stable... for the time being. I should be able to handle the rest of our operation from here.\n\nEmberthal arrived while you were in the field. She and her allies are surveying the area from the cliffs above. It would be wise to check in with her, I think. We would not want her to attempt taking the Reach alone.", completion = "This was our training ground... and for many, it became our resting place.\n\nSo many secrets remain here. So many questions. With luck, we will find answers.", objectives = "Meet with Emberthal above the cliffs of Morqut Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74857] = { id = 74857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouse Detective", description = "Normally I'd chase strangers off my property, but today's an exception.\n\nMy sniffin' mouse has gone missing. It's not like Persii to ignore me when I call for her...\n\nI can't smell as good as other niffen, so I can't tend to the harvest without her help.\n\nPoor thing must be so scared, out there all on her own. Please, you gotta find Persii!", completion = "That niffen needs his mouse, huh? Hmm...", objectives = "Search for the missing mouse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74858] = { id = 74858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agrulculture", description = "The niffen say that sniffin' mice have great noses. They can make their way through the caverns and track down the fastest racing snails. Even sniff out glow spores ready for harvest.\n\nBut I have a good nose, too. Maybe I could even sniff out those glow spores!\n\nLet's collect the harvest for the hermit. That will show him it's okay that his mouse friend isn't here--because I can fill in!", progress = "Sniffin' mice must make this a lot easier. But I don't mind hard work!", completion = "See? Just as good as a sniffin' mouse!\n\nI hope the hermit agrees...", objectives = "Collect 6 Glow Spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74859] = { id = 74859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporemoth Exterminator", description = "Looks like sporemoths are wrecking these crops.\n\nIf they keep eating all the spores, the hermit won't have anything to harvest.\n\nWe need to cull the sporemoths. That should help keep the harvest thriving--and show that I know how to take care of a farm.", progress = "If we don't keep the pests under control, the spores won't grow.", completion = "That should help keep the spores healthy for now.", objectives = "Kill 10 Sporemoths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74860] = { id = 74860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Introduction", description = "It's time to deliver the harvest to the hermit. When he sees what good work we did, maybe he'll hire me as a farmhand!\n\nI, uh... tried talking to him once before. Wanted to ask if he needed a helper.\n\nDoesn't seem to like guests, though. Especially drogbar. So I got nervous and ran off.\n\nYou were looking for his mouse. Could you introduce us?", progress = "You have to find Persii before it's too late!", completion = "That drogbar ran off because he's guilty. I'm sure of it!", objectives = "Deliver the harvest and introduce Agrul to Yarren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74861] = { id = 74861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unfriendly Confrontation", completion = "I never should have worked for Malrogg...", objectives = "Find Agrul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74862] = { id = 74862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74864] = { id = 74864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74866] = { id = 74866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journal Entry: Experiments", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", progress = "{name}, find any information of interest?", completion = "Good. More of our history in the voice of someone who lived it.\n\n<Azurathel reads over the journal entry growing more and more stoic.>\n\nThis is... disturbing. As soldiers we knew there was a degree at which we were expendable. But to read this...\n\nThank you for bringing this to me. We need to get this translated so others can read it.", objectives = "Collect a Journal Entry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74867] = { id = 74867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74869] = { id = 74869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primordial Answers", description = "Revelations await us within this vault. Perhaps we'll find a way to protect ourselves against Primalist magic. The elementals hiding in these vaults are wild, ancient, and free of Primalist control. Perhaps they hold the secret to helping the elementals on the surface.\n\nI have an idea. We'll need four primordial cores. Then we can construct a talisman that can purify and remove the influence of Primalist control from the elementals outside.\n\nIf you help us, I will share what we have found here.", progress = "Have you found the cores?", completion = "These primordial cores are all I need here. \n\nPlease let me share with you the things I have found. May they help you in your efforts.", objectives = "Obtain a Primordial Earth, Fire, Water and Storm Core from the elementals within the Zskera Vaults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74871] = { id = 74871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of Life: The Forbidden Reach", description = "The Forbidden Reach is enveloped with the vibrancy of the Dragon Isles.\n\nGo explore and capture sparks, but stay wary for any combatants you may encounter.", progress = "Right out that door. Can't miss it.", completion = "The Accord thanks you, no doubt.", objectives = "Collect 50 Sparks of Life in The Forbidden Reach, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74874] = { id = 74874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74875] = { id = 74875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spring Awakening", description = "If you're looking for something to do, I hear there are mages in the settlements near capital cities - Razor Hill, Brill, Bloodhoof Village, and Falconwing Square - who have been recruiting egg hunters for help with some research they're doing. I'm not sure of the particulars, but I'm sure they'd tell you.", completion = "Yes! Yes, I think I have just the task for you...", objectives = "Talk to a Spring Gatherer in Razor Hill, Brill, Bloodhoof Village, or Falconwing Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74876] = { id = 74876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Buddy System", description = "Oh, hello there. Was I speaking my thoughts out loud again?\n\nI don't mean to trouble others with my problems, but...\n\nI'm a sniffenseeker, you see. We find unique and amazing places all over the cavern! But we have an important rule here in Loamm--we always follow the buddy system. Nobody digs alone!\n\nI've had the same buddy since we were pups, but she's too busy to dig anymore. I found this interesting new smell. Before, I had a buddy...\n\nSay, how do you feel about being a stand-in dig partner?", progress = "Just let me know if you decide you'd like to go with me!", completion = "You're a good partner. We should do more digs together. We could even have a dig team name! Like... the diggies? Duggies? I'll think about it.\n\nI'm not sure when my main dig buddy will have time to go again, so I'm glad to have met you, friend!", objectives = "Go on a dig adventure with Myrrit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74877] = { id = 74877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Friends", description = "Really, I have fun digging with you. I do! Please, don't take this badly, but... I miss my best friend.\n\nI don't blame her for being busy. She was kidnapped, and she is the princess! I know she doesn't have lots of time. I just wish... \n\n...I don't know.\n\nMaybe I wish things were the way they used to be, when she wanted to dig with me.", progress = "It's Effervesta's favorite snack...", completion = "Maybe she forgot, or she's still busy.", objectives = "Set up a dig for Myrrit and Effervesta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74879] = { id = 74879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrosive Counterbalance" }
quests[74880] = { id = 74880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journal Entry: Relics", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", progress = "{name}, find any information of interest?", completion = "I think I remember Ebyssian talking about the Hammer of Khaz'goroth and how it was used to expunge him of corruption.\n\nGiven it did not work on us I can only assume I was never corrupted. I am taking this as a win!\n\nThank you for this information, {name}. I will add this to our collection.", objectives = "Collect a Journal Entry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74882] = { id = 74882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Circuit - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74883] = { id = 74883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journal Entry: The Creches", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", progress = "Have you found any more journal entries of Adamanthia?", completion = "This is just creepy. I know what happened and yet this is crawling up my scales like one of those annoying beetles. \n\nI will get a translated copy added to the collection so others can read it. \n\nI am very much wondering whose side this Adamanthia was actually on.", objectives = "Find a Journal Entry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74889] = { id = 74889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caldera Cruise", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74892] = { id = 74892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaqali Elders" }
quests[74896] = { id = 74896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journal Entry: Silence", description = "<This ancient page is bound in ambient magic and scribed in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", progress = "This may prove quite insightful.", completion = "So they kept us secret even from the other aspects. Malygos knew, but from what I have heard, he could be just as disconnected as Neltharion.\n\nI will add this journal entry to our translated collection. Thank you, {name}.", objectives = "Find a Journal Entry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74899] = { id = 74899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caldera Cruise - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74900] = { id = 74900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Receiving Stone: Final Warning", description = "<This receiving stone still holds ancient words from Neltharion in an old draconic dialect.>\n\n<The dracthyr scalecommanders would have a great interest in the contents of this document.>", progress = "What have you found?", completion = "Oh... I remember that tone of voice. \n\nI am starting to think Adamanthia may have crossed a line, and she could not walk back.\n\nI will get the translation of this stone added to our transcripts.", objectives = "Find a Receiving Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74901] = { id = 74901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sending Stone: Protest", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", progress = "What have you found?", completion = "Well, good to see a black dragon standing up for us, even if it was too little too late.\n\nI wonder what this \"Aberrus\" is. If it is another place where dracthyr were held then we may need to find it.\n\nI will add this to the translated logs. I recommend taking a look as you find more of these.", objectives = "Find a Sending Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74902] = { id = 74902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sending Stone: Initial Report", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", progress = "What have you found?", completion = "They knew we were not broken.\n\nTHEY KNEW.\n\nI think we knew that, but to read this... it just feels like more oil on the pyre. \n\nStill, I thank you for bringing this to us. I will get this translated for everyone to read and added to the logs.", objectives = "Find a Sending Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74903] = { id = 74903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sending Stone: The Prisoner", description = "<This sending stone still holds ancient words spoken from Adamanthia to Neltharion in an old draconic dialect.>\n\n<Scalecommanders would have a great interest in the contents of this document.>", progress = "What have you found?", completion = "Huh. If this is right, then Raszageth was awake the entire time we were in stasis.\n\nI can see why she was so mad. I still do not agree with her or her methods, but anyone trapped for more than ten or twenty thousand years in a hole with little light is going to go mad. \n\nI will get the translated version added to the transcripts we have been handing around. Thank you for this, {name}.", objectives = "Find a Sending Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74905] = { id = 74905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researchers Under Fire" }
quests[74906] = { id = 74906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researchers Under Fire" }
quests[74908] = { id = 74908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Adventures", description = "Cataloger Daela is here to investigate places of wonder and mystery. Skyfox Den and Caldera of the Menders look especially promising.\n\nCompleting her quests will unlock her Envoy Tasks today. You will be able to unlock other factions' Envoy Tasks tomorrow.", completion = "Fascinating! We must plan our next steps wisely. I'll give you detailed instructions.", objectives = "Speak with Cataloger Daela.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74909] = { id = 74909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Catches", description = "Turik is here to investigate the riches of the sea across the Forbidden Reach on behalf of the Iskaara Tuskarr.\n\nCompleting this quest will unlock his Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", completion = "The fish are really biting today!", objectives = "Speak with Turik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74910] = { id = 74910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Foes", description = "Storykeeper Ashekh is here to scout for enemies of the Maruuk.\n\nCompleting this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", completion = "Let me consider our enemies' strength. There is much to be done.", objectives = "Speak with Storykeeper Ashekh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74911] = { id = 74911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Horizons", description = "Kraxxus represents the strength of Valdrakken Accord here on Forbidden Reach.\n\nCompleting this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", completion = "Welcome to the Forbidden Reach, friend!", objectives = "Speak with Kraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74912] = { id = 74912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Legacy", description = "<As you stare into the cracked titan gem, a voice echoes through your mind.>\n\n{name}! This is Nozdormu. \n\nThe time to redeem the legacy of your creator, Neltharion, is at hand. \n\nYou hold a vital piece to the artifact Neltharion once used to control you and all of the dracthyr.\n\nMeet me in Valdrakken. There is much to discuss.", completion = "Thank you for coming. I have been preparing for this moment for quite some time.", objectives = "Meet Nozdormu in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74913] = { id = 74913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of an Artifact", description = "Emberthal aided me in discovering the Oathbinder. This was the artifact Neltharion used to control you all.\n\nI have been scouring the timeline to discover how it was made to forge a counterpart to it to protect your kind.\n\nThis gem you've recovered is just the key I need to move my studies forward.\n\nYou and I shall next meet within Zaralek Cavern, where you once fought over the broken Oathbinder.\n\nIt is there we will find the secrets to forge your own weapon to fight against tyranny.", progress = "Let us see what we find within the caverns.", completion = "You hold the memories of how to forge the counter to the Oathbinder. \n\nIt is time for you to embark on this path.", objectives = "Meet Nozdormu within Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74923] = { id = 74923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Takes a Village to Make an Artifact", description = "You must go now and seek aid to create the key components to forge a new glove.\n\nEssence of Order is normally difficult to find, but the memories you have acquired will allow you to recover them at many locations.\n\nThis new glove will be one to empower your allies and your community... which means you will have to rely on others to aid you in this.\n\nTake the memories you've recovered and use them to teach others how to craft these parts.", progress = "Have you recovered all the items? You will have to request the aid of your fellow adventurers to create all the pieces.", completion = "Fine work! You've gone through great lengths to craft these individual parts. \n\nNow we must uncover the last part to bring it all together.\n\nThe essence of the first black dragon aspect.", objectives = "Use the Ancient Memories to teach others or yourself how to forge the parts needed for your new artifact.\n\nYou must use Work Orders to get the components from your allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74924] = { id = 74924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasz'uro, the Unbound Legacy", description = "Through my research, I've uncovered the last piece to make this artifact truly a counter to the Oathbinder.\n\nThe essence of Neltharion.\n\nIt is here that I can finally aid the dracthyr. We shall travel to the Maelstrom to see his final moments.\n\nWith his essence, we shall finish crafting your artifact, Nasz'uro, the Unbound Legacy.\n\nSpeak to me when you are ready.", completion = "Your artifact is now complete. Wield it knowing no one may ever control the {race} ever again. Your destiny is your own.", objectives = "Speak with Nozdormu to travel to the Maelstrom to view Neltharion's defeat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74925] = { id = 74925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caldera Cruise - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74939] = { id = 74939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimstone Scramble", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74942] = { id = 74942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grime Lies Where You're Killing Slimes", description = "Did you see that? Some of the slimes are leaving little piles of grime behind. Hmm...\n\nMelly makes stuff out of all kinds of things. You think she could use the grime to help out Tempo? I bet she could.", progress = "Time grime! I'm on a roll here.", completion = "Nice! I'll hand these off to Melly. Along with my list of excellent slime rhymes.", objectives = "Collect Time Grime.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74943] = { id = 74943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimstone Scramble - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
