quests[74945] = { id = 74945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guanite Gambit" }
quests[74946] = { id = 74946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Place of Refuge", description = "Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them.\n\nThis Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. \n\nWhile her reasoning is sound, this is also the perfect location for a trap.\n\n{name}, I know you vouch for her, so I will give her the benefit of the doubt.\n\nLet us hope your trust in her is not misplaced.", completion = "The good news is that we have found the other tauren.\n\nThe bad news is that this Bovan he seeks isn't here.\n\nThe irritating news is that everyone wants me dead.", objectives = "Meet Baine and Tomul at Toghusuq Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74948] = { id = 74948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Amethyst Softshell", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Crok, what a beaut. And they come from the ocean? Can't imagine one of my snails handling all that salt. \n\nI'm sure Slick is impressed.", objectives = "Summon a max-level Amethyst Softshell battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74949] = { id = 74949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Archetype of Vigilance", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "That... is the weirdest, fanciest snail I have ever seen.\n\n If Slick isn't impressed by this fellow, I don't know what's going to impress him.", objectives = "Summon a max-level Archetype of Vigilance battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74950] = { id = 74950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Blackchasm Crawler", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Now THIS is a snail who enjoys a good cavern! I'm sure Slick can relate. \n\nI certainly do.", objectives = "Summon a max-level Blackchasm Crawler battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74951] = { id = 74951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmering Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74952] = { id = 74952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Microlicid", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", completion = "Not sure what's so micro about that critter, but they sure got a shell on them. Though I guess most snails are micro next to Slick!", objectives = "Summon a max-level Microlicid battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74953] = { id = 74953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heavy Crown", description = "I was really down when Effervesta didn't come like she said she would.\n\nBut I understand that she's so busy, what with being kidnapped and all of her duties. I don't blame her.\n\nI want to tell her how much that time meant to me when we were pups, though. That I'll be here for her if she ever needs me. Then at least she knows I'm still here.\n\nCan you help me get her attention long enough to say what I need to?", progress = "I don't want to bother her...", completion = "Now that I have her here, I don't know what to say!", objectives = "Help create a time for Myrrit to talk to Effervesta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74954] = { id = 74954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmering Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74955] = { id = 74955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Egg-centric Discovery", description = "Have you seen the new eggs this year? Well, you could say they are quite egg-citing!\n\n... Well, I'll get to the point. These new eggs that we've discovered will appear and vanish within minutes! That sounds quite egg-straordinary, right?\n\nLet me know when you're ready and we'll see to it that those eggs appear, but be quick! They'll be gone before you know it.\n\nI'll trade you a more permanent egg when you return with vanishing eggs.", objectives = "Talk to a Spring Gatherer in Razor Hill, Brill, Bloodhoof Village, or Falconwing Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74956] = { id = 74956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmering Slalom - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74959] = { id = 74959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Mudshell Conch", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Some people see a mudshell conch and think, what's so special? But me, I appreciate the simple things. There's beauty in that. \n\nI'm sure Slick agrees!", objectives = "Summon a max-level Mudshell Conch battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74960] = { id = 74960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Predatory Helicid", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Predatory, huh? Just keep that critter away from my buckets. I don't need any accidents. Not again.\n\n<Briggul stares off at the distance, her eyes haunted.>\n\nBut yeah, I'm sure Slick is feeling that fighting spirit.", objectives = "Summon a max-level Predatory Helicid battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74961] = { id = 74961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Prismatic Softshell", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Prismatic, huh? That's a fancy term for pretty colors? Well this snail fits the bill. I hope Slick doesn't get too self-CONCH-scious about it. Ha! \n\nHe's plenty pretty himself.", objectives = "Summon a max-level Prismatic Softshell battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74962] = { id = 74962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Rapana Whelk", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Don't let that one fool you, {name}. I can sense the shell of a killer. Hope Slick is more inspired than spooked!", objectives = "Summon a max-level Rapana Whelk battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74963] = { id = 74963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Rusty Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Oh! Rusty like the COLOR. I was worried how you were caring for this little one. Made me scared for Slick here!\n\nWhew, that's a relief.", objectives = "Summon a max-level Rusty Snail battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74964] = { id = 74964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Scooter the Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Look at the shell on that one! And you said a child gave them to you?\n\nGlad they ended up in your hands! Runts tend to behave... questionably toward snails.", objectives = "Summon a max-level Scooter the Snail battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74965] = { id = 74965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Shelly", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Now \"Shelly\" is a name I can get behind. Maybe this critter is Slick's long-lost cousin!\n\n<Briggul looks over the progenitor snail again.>\n\nHuh. Maybe... very long-lost.", objectives = "Summon a max-level Shelly battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74966] = { id = 74966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Silkbead Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "Just look at that critter move! The silkbead snail has a particularly silky consistency to its mucus. \n\nNot sure Slick can really learn from that, but hey. You can.", objectives = "Summon a max-level Silkbead Snail battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74967] = { id = 74967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Spireshell Snail", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "I'm sure Slick a-SPIRES to be as strong as your snail there! Ha!\n\n<Briggul wipes a joyful tear from her eye.>\n\nI should bring that one to the next race. The other trainers are going to eat it up.", objectives = "Summon a max-level Spireshell Snail battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74968] = { id = 74968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snailspiration: Zoom", description = "I smell a snail on you, but it's strange. You holding out on me?\n\nNot many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", progress = "Show me that snail! Let's inspire Slick to be his best slimy self.", completion = "That... that's ZOOM! The legendary racing snail of Highmountain!\n\nCrok me, I have to tell cousin Boomboom about this. What an absolute honor. For Slick as well, I'm sure.", objectives = "Summon a max-level Zoom battle pet and show it to Briggul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74972] = { id = 74972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loamm Roamm", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
