quests[74977] = { id = 74977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loamm Roamm - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74983] = { id = 74983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authentic Authorization", description = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course!\n\nIf I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans!\n\nIf you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", progress = "Did you find anything?", completion = "What an amazing find. The mind reels. \n\nOh, and I can't wait to write about this discovery and publish our findings. We will publish... or perish trying!", objectives = "Find 10 Neltharion-Signed Notes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74984] = { id = 74984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authentic Authorization", description = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course!\n\nIf I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans!\n\nIf you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", progress = "Did you find anything?", completion = "What an amazing find. The mind reels. \n\nOh, and I can't wait to write about this discovery and publish our findings. We will publish... or perish trying!", objectives = "Find 3 Random Scribblings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
