quests[74994] = { id = 74994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hraxian's Unbreakable Will", objectives = "I have forgotten much in the course of my life. \n\nTwice now you have helped me recover a valuable memory.\n\n<Veritistrasz smiles faintly.>\n\nPerhaps I should take Tellywin up on his offer to write memoirs, if just for my own sake. \n\nYou have done so much for myself and these folks. I hope one day to repay the favor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74996] = { id = 74996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Difficult Legacy", progress = "It is always a pleasure, {name}.", completion = "Thank you for being here, {name}. You have both given me a lot to think about.\n\nI will stay with Veritistrasz for now, but I look forward to when we next meet.", objectives = "Talk to Voraxian and Veritistrasz at Rusza'thar Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
