quests[75012] = { id = 75012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[75018] = { id = 75018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Dark", description = "My Blacktalon forces continue to secure the laboratory, but I think we are done here, {name}.\n\nWe have secured some slitherdrakes to take us down to the central platform. From there we can continue below, to where Sarkareth fell.\n\nI am certain Ebyssian and Emberthal will benefit from our presence.", completion = "Good, you have made it. I could use your help, {name}.", objectives = "Meet with Ebyssian and Emberthal in the room at the bottom of the laboratory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75022] = { id = 75022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vinyeti" }
quests[75023] = { id = 75023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of Sindragosa and Malygos", description = "I admit, I forgot about this phenomenon. Blue dragons who meet violent ends occasionally have some lingering arcane energy.\n\nThat energy may manifest in various ways once their essences are laid to rest. \n\nLuckily, it is a simple enough process to dispel them. Simply wave anything through the energy and it will dissipate. \n\nI shall investigate the essences of Sindragosa and Malygos within this gravestone while you handle that.", progress = "How strange that these memories still linger...", completion = "That should do it, though it is odd not all of the memories were dispelled as quickly as I had hoped...\n\nLet us speak with Kalecgos to let him know we should keep an eye on this.", objectives = "Dispel the lingering memories of Sindragosa and Malygos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75024] = { id = 75024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneaky Pebbles", description = "Beetles are swarming our support creche! Some of them are now eating pieces of broken Infusers, and that's making them stronger. We keep trying to smush them, but they won't stay smushed.\n\nNow it's harder to get rid of them, but we have a plan. We've discovered that hitting them with pieces of broken Infusers can weaken them again!\n\nDo you mind helping us clear out these Infused Beetles?", progress = "Have you cleared those beetles yet?\n\nI knew we'd discover new wildlife when we returned to the Reach, but this isn't what I wanted. Also, I'm getting really tired of treating bug bites.", completion = "Amazing work! Now we it will be easier for us to reclaim the support creche.", objectives = "12 Infused Beetles Defeated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75025] = { id = 75025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Day for Rolling", description = "I have an... odd request for you. I need help with some squirrels. Primalists have corrupted them, and it's making them unstable!\n\nI know just the thing to cool them off. Snow! If you could roll the creatures up in a big snowball, they would cool down as the snow melts. Ingenious, yes?\n\nCan you help me?  I can't concentrate or finish my cataloguing, and I don't have time to write more eloquent prose. If nothing else, think of the loss to great literature!", progress = "Have you, uh, rolled up those critters yet?\n\nYou make your work look so easy. I'm sure it will be... snow problem at all. \n\nForgive me. It's the heat.", completion = "Thank you for helping me! I can finally relax for a bit.\n\nI'll thank you by recording your deeds in my records. I might also write a character inspired by you in my next novel. I'll claim it's an original character, but we'll both secretly know it's you.", objectives = "Save 14 Overcharged Critters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75026] = { id = 75026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to the Highest Height!", description = "Tuskarr children sure do love kites! I've seen some of them running around with them outside Morqut Village. I've also seen a lot of those kites stuck in trees.\n\nCan you do me a favor? Could you lasso some of those kites and pull them down? They'll probably fall down in pieces, but the children can always put their kites back together. Who knows? Maybe it will teach them to be more careful.", progress = "Do you have any kite pieces yet?\n\nI'm glad those kids have something to do. If they didn't, one of them would follow me around all day, and I hate it when they do that.", completion = "Fantastic work! Fixing kites should keep the children busy and out of trouble... for a little while, at least.\n\nThat's a good thing. Those kids get everywhere.", objectives = "Collect 12 kite pieces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75028] = { id = 75028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All the Broken Pieces", description = "Emberthal is in mourning. In truth, she has been grieving for Sarkareth for some time now.\n\nThe way forward is for her to determine. We can only be there to support her along the way.\n\nThere are shards of Sarkareth's signet scattered all over this room. Would you gather them? I believe she would appreciate the gesture.", progress = "<Emberthal is in no mood to speak just yet.>", completion = "<Emberthal looks up as you approach.>", objectives = "Collect the shards of Sarkareth's signet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75029] = { id = 75029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Legacy, Reforged", description = "Grief is a painful burden to bear. It warms my heart to see Emberthal emerge from her sorrow and focus on her people. The pain of her loss will ebb, in due time.\n\nWe need to inform Alexstrasza and the others of what has transpired here... and of the future of the black dragonflight.\n\nWith all that you have done to ensure that we have a chance at a future, I would like you to be there.", progress = "We shall see you there, {name}.", completion = "A new path. But one I accept gladly.", objectives = "Meet Ebyssian at the Seat of the Aspects in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75030] = { id = 75030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Catastrophe!" }
